        'value' => 
        array (
          'code' => '"SELECT p.*, c.uuid AS contract_uuid, c.contract_number, ct.name AS contractor_name,\\n        r.uuid AS report_uuid, r.number AS report_number, r.period_start, r.period_end,\\n        CONCAT(cb.first_name, \' \', cb.last_name) AS created_by_name,\\n        CONCAT(ab.first_name, \' \', ab.last_name) AS approved_by_name,\\n        CONCAT(pb.first_name, \' \', pb.last_name) AS paid_by_name\\n        FROM payments p\\n        JOIN contracts c ON c.id = p.contract_id\\n        JOIN contractors ct ON ct.id = c.contractor_id\\n        JOIN reports r ON r.id = p.report_id\\n        JOIN users cb ON cb.id = p.created_by\\n        LEFT JOIN users ab ON ab.id = p.approved_by\\n        LEFT JOIN users pb ON pb.id = p.paid_registered_by"',
